text = "apple banana apple cherry banana apple"
words = text.split()
counts = {}
for w in words:
    counts[w] = counts.get(w, 0) + 1
print(counts)  # {'apple': 3, 'banana': 2, 'cherry': 1}

from collections import Counter
c = Counter(words)
print(c.most_common(1))  # [('apple', 3)]

两种方式均得 apple 出现 3 次。
